{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.bill import per_person"
  ],
  "tests": [
    {
      "name": "test_three_people_split_100_rounds_up",
      "intent": "the example from the task: three people splitting 100.00 each pay 33.34",
      "code": "# intent: the example from the task: three people splitting 100.00 each pay 33.34\ndef test_three_people_split_100_rounds_up():\n    assert per_person(Decimal(\"100.00\"), 3) == Decimal(\"33.34\")\n"
    },
    {
      "name": "test_rounding_up_when_exact_split_has_more_than_two_decimals",
      "intent": "rounding up to the next cent when the exact share has more than two decimal places",
      "code": "# intent: rounding up to the next cent when the exact share has more than two decimal places\ndef test_rounding_up_when_exact_split_has_more_than_two_decimals():\n    assert per_person(Decimal(\"0.01\"), 3) == Decimal(\"0.01\")\n"
    },
    {
      "name": "test_no_rounding_when_exact_split_is_to_the_cent",
      "intent": "no rounding when the exact split is already to the cent",
      "code": "# intent: no rounding when the exact split is already to the cent\ndef test_no_rounding_when_exact_split_is_to_the_cent():\n    assert per_person(Decimal(\"90.00\"), 3) == Decimal(\"30.00\")\n"
    },
    {
      "name": "test_tip_percent_is_applied_before_rounding_up",
      "intent": "tip percentage is applied before rounding up",
      "code": "# intent: tip percentage is applied before rounding up\ndef test_tip_percent_is_applied_before_rounding_up():\n    assert per_person(Decimal(\"100.00\"), 3, Decimal(\"10\")) == Decimal(\"36.67\")\n"
    },
    {
      "name": "test_zero_people_raises_value_error",
      "intent": "zero people raises ValueError",
      "code": "# intent: zero people raises ValueError\ndef test_zero_people_raises_value_error():\n    with pytest.raises(ValueError):\n        per_person(Decimal(\"100.00\"), 0)\n"
    },
    {
      "name": "test_negative_people_raises_value_error",
      "intent": "negative people raises ValueError",
      "code": "# intent: negative people raises ValueError\ndef test_negative_people_raises_value_error():\n    with pytest.raises(ValueError):\n        per_person(Decimal(\"100.00\"), -1)\n"
    }
  ]
